    },
    "hypotheses_testable": {
      "pass": true,
      "detail": "All 7 hypotheses have explicit null hypotheses, test strategies, and quantitative verdict rules. H-NOISE-01 is the critical noise-detection hypothesis and is well-designed. Verdict rules use appropriate thresholds (Bonferroni correction, 95th percentile of permutation null)."
    },
